import type { AnonymousOnboardingFlowState } from "../anonymous-onboarding-types";

/** Load/save port for onboarding flow persistence (localStorage, memory, HTTP, …). */
export interface OnboardingFlowPersistencePort {
  readonly storageKey?: string;
  /** `null` when absent or unreadable; sync API matches existing wizard behaviour. */
  load(): AnonymousOnboardingFlowState | null;
  save(state: AnonymousOnboardingFlowState): void;
}

import type { AnonymousOnboardingFlowState } from "../anonymous-onboarding-types";
import type { OnboardingFlowPersistencePort } from "./onboarding-flow-persistence-port";

export function createLocalStorageOnboardingFlowPersistence(options: {
  storageKey: string;
}): OnboardingFlowPersistencePort {
  const { storageKey } = options;
  return {
    storageKey,
    load() {
      if (typeof localStorage === "undefined") return null;
      try {
        const raw = localStorage.getItem(storageKey);
        return raw ? (JSON.parse(raw) as AnonymousOnboardingFlowState) : null;
      } catch {
        return null;
      }
    },
    save(state: AnonymousOnboardingFlowState) {
      if (typeof localStorage === "undefined") return;
      try {
        localStorage.setItem(storageKey, JSON.stringify(state));
      } catch {
        /** ignore quota / privacy mode */
      }
    },
  };
}

import type { AnonymousOnboardingFlowState } from "../anonymous-onboarding-types";
import type { OnboardingFlowPersistencePort } from "./onboarding-flow-persistence-port";

export type MemoryOnboardingPersistenceOptions = {
  /** Initial snapshot; reads/writes mutate this reference. */
  snapshot?: AnonymousOnboardingFlowState | null;
};

export function createMemoryOnboardingFlowPersistence(
  options?: MemoryOnboardingPersistenceOptions,
): OnboardingFlowPersistencePort {
  let value = options?.snapshot ?? null;
  return {
    storageKey: "memory:onboarding-flow",
    load() {
      return value;
    },
    save(state: AnonymousOnboardingFlowState) {
      value = state;
    },
  };
}

export type { OnboardingFlowPersistencePort } from "./onboarding-flow-persistence-port";
export { createLocalStorageOnboardingFlowPersistence } from "./create-local-storage-onboarding-flow-persistence";
export {
  createMemoryOnboardingFlowPersistence,
  type MemoryOnboardingPersistenceOptions,
} from "./create-memory-onboarding-flow-persistence";

import { DEFAULT_VAT_PROTOTYPE_PRESET_ID } from "./lib/vatPrototypePresets";
import type { AnonymousOnboardingFlowState } from "./anonymous-onboarding-types";
import { DEFAULT_CONTEXT } from "./anonymous-onboarding-flow-helpers";

export const DEFAULT_ONBOARDING_FLOW_STATE: AnonymousOnboardingFlowState = {
  step: "request",
  requestOrigin: "",
  drafts: [],
  summaryIncludedDraftIds: [],
  context: DEFAULT_CONTEXT,
  wizardInitialStep: "intent",
  prototypeVatPresetId: DEFAULT_VAT_PROTOTYPE_PRESET_ID,
  companyFieldHints: {},
  summaryKlantenportaalByPersonId: {},
};

export function hydrateOnboardingFlowStateFromStored(
  stored: AnonymousOnboardingFlowState | null | undefined,
): AnonymousOnboardingFlowState {
  if (!stored) return DEFAULT_ONBOARDING_FLOW_STATE;
  return {
    ...DEFAULT_ONBOARDING_FLOW_STATE,
    ...stored,
    context: { ...DEFAULT_CONTEXT, ...stored.context },
    companyFieldHints: stored.companyFieldHints ?? {},
    summaryKlantenportaalByPersonId: stored.summaryKlantenportaalByPersonId ?? {},
  };
}

