import { AnonymousOnboardingCompanyStep } from "../components/anonymous-onboarding-company-step/AnonymousOnboardingCompanyStep";
import { AnonymousOnboardingCustomerStep } from "../components/anonymous-onboarding-customer-step/AnonymousOnboardingCustomerStep";
import { AnonymousOnboardingExtrasStep } from "../components/anonymous-onboarding-extras-step/AnonymousOnboardingExtrasStep";
import { AnonymousOnboardingInvoicingStep } from "../components/anonymous-onboarding-invoicing-step/AnonymousOnboardingInvoicingStep";
import { AnonymousOnboardingOriginStep } from "../components/anonymous-onboarding-origin-step/AnonymousOnboardingOriginStep";
