import { AnonymousOnboardingSummaryStep } from "../components/anonymous-onboarding-summary-step/AnonymousOnboardingSummaryStep";
import { RegistrationProcessingDialog } from "../components/registration-processing-dialog";
import { STABLE_STEP_MIN_HEIGHT } from "../components/certification-request-wizard/use-certification-request-wizard-view";
import { OnboardingStepper, StepLayout } from "@procertus-ui/ui-lib";

export {
  AnonymousOnboardingCompanyPrefillSkeleton,
  AnonymousOnboardingContextField,
} from "./anonymous-onboarding-shared-fields";
import { mergeRegistrationChromeCopy } from "./anonymous-onboarding-registration-chrome-copy";
import { AnonymousOnboardingShell } from "./anonymous-onboarding-shell";
import type { AnonymousOnboardingFlowViewProps } from "./anonymous-onboarding-flow-view-props";
import type { OnboardingStep } from "./anonymous-onboarding-types";
import { ONBOARDING_STEPS } from "./anonymous-onboarding-types";
import { useAnonymousOnboardingRegistrationLayoutModel } from "./use-anonymous-onboarding-registration-layout-model";

export function AnonymousOnboardingFlowView(props: AnonymousOnboardingFlowViewProps) {
  const rb = useAnonymousOnboardingRegistrationLayoutModel(props);

  const {
    step,
    certificationPhaseTitle,
    certificationPhaseDescription,
    registrationPhaseTitle,
    registrationPhaseDescription,
    onSignInClick,
    certificationWizardProps,
    registrationSubmitOpen,
    onRegistrationSubmitOpenChange,
    registrationProgress,
    registrationStepIndex,
    registrationSimulationLabels,
    steps,
    activeStep,
    goToOnboardingStep,
    primaryAction,
    backAction,
    cancelAction,
    requestOrigin,
    setRequestOrigin,
  } = props;

  if (step === "request") {
    return (
      <AnonymousOnboardingRequestStep
        pageTitle={certificationPhaseTitle}
        pageDescription={certificationPhaseDescription}
        onSignInClick={onSignInClick}
        certificationWizardProps={certificationWizardProps}
      />
    );
  }

  const chromeStep = step as Exclude<OnboardingStep, "request">;
  const registrationChrome = mergeRegistrationChromeCopy(
    chromeStep,
    props.registrationChromeOverrides?.[chromeStep],
  );

  return (
    <>
      <AnonymousOnboardingShell
        pageTitle={registrationPhaseTitle}
        pageDescription={registrationPhaseDescription}
        onSignInClick={onSignInClick}
      >
        <StepLayout
          className="w-full"
          minHeight={STABLE_STEP_MIN_HEIGHT}
          variant="onboarding"
          stepper={
            <OnboardingStepper
              steps={steps}
              activeStep={activeStep}
              onStepChange={(index) => {
                const nextStep = ONBOARDING_STEPS[index];
                if (nextStep) {
                  goToOnboardingStep(nextStep);
                }
              }}
              interactive
            />
          }
          title={registrationChrome.title}
          description={registrationChrome.description}
          backAction={backAction}
          primaryAction={primaryAction}
          cancelAction={cancelAction}
        >
          {step === "origin" ? (
            <AnonymousOnboardingOriginStep
              originFieldBase={rb.originFieldBase}
              requestOrigin={requestOrigin}
              setRequestOrigin={setRequestOrigin}
            />
          ) : null}
          {step === "customer" ? <AnonymousOnboardingCustomerStep model={rb} /> : null}
          {step === "company" ? <AnonymousOnboardingCompanyStep model={rb} /> : null}
          {step === "invoicing" ? <AnonymousOnboardingInvoicingStep model={rb} /> : null}
          {step === "extras" ? <AnonymousOnboardingExtrasStep model={rb} /> : null}
          {step === "summary" ? <AnonymousOnboardingSummaryStep model={rb} /> : null}
        </StepLayout>
      </AnonymousOnboardingShell>

      <RegistrationProcessingDialog
        open={registrationSubmitOpen}
        onOpenChange={onRegistrationSubmitOpenChange}
        progress={registrationProgress}
        activeStepIndex={registrationStepIndex}
        steps={registrationSimulationLabels}
      />
    </>
  );
}

