import { PageHeader, PublicRegistryAppShell } from "@procertus-ui/ui";
import procertusLogo from "@procertus-ui/ui/assets/Procertus logo.svg";
import type { ReactNode } from "react";

export type OnboardingShellProps = {
  pageTitle: string;
  pageDescription: string;
  onSignInClick: () => void;
  children: ReactNode;
};

/** Public onboarding chrome: logo, page header, Sign in — used by certification + registration phases. */
export function OnboardingShell({
  pageTitle,
  pageDescription,
  onSignInClick,
  children,
}: OnboardingShellProps) {
  return (
    <PublicRegistryAppShell
      header={{
        logo: (
          <img
            src={procertusLogo}
            alt="PROCERTUS, certification that builds trust"
            className="h-8 w-auto dark:brightness-0 dark:invert"
          />
        ),
        onLogin: onSignInClick,
      }}
      hideFab
    >
      <div className="mx-auto flex w-full max-w-7xl flex-col gap-region p-boundary">
        <PageHeader title={pageTitle} description={pageDescription} />
        {children}
      </div>
    </PublicRegistryAppShell>
  );
}

import { Field, FieldContent, FieldDescription, FieldLabel, Input } from "@procertus-ui/ui";
import { PrefillFieldSkeleton } from "@procertus-ui/ui";

import type { CustomerContext } from "../../../anonymous-onboarding/anonymous-onboarding-types";
import type { CompanyFormFieldKey } from "../../../anonymous-onboarding/lib/vatPrototypePresets";

/** Single labeled input used across customer and company onboarding steps. */
export function OnboardingContextField({
  id,
  label,
  value,
  onChange,
  placeholder,
  readOnly,
  description,
}: {
  id: keyof CustomerContext;
  label: string;
  value: string;
  onChange: (id: keyof CustomerContext, value: string) => void;
  placeholder?: string;
  readOnly?: boolean;
  description?: string;
}) {
  return (
    <Field>
      <FieldLabel htmlFor={String(id)}>{label}</FieldLabel>
      <FieldContent>
        <Input
          id={String(id)}
          value={value}
          placeholder={placeholder}
          readOnly={readOnly}
          onChange={(event) => onChange(id, event.target.value)}
        />
        {description ? <FieldDescription>{description}</FieldDescription> : null}
      </FieldContent>
    </Field>
  );
}

