import type { Meta, StoryObj } from "@storybook/react-vite";
import type { ReactNode } from "react";
import { useLayoutEffect, useMemo, useState, type ComponentType } from "react";

import { OnboardingStepper, StepLayout } from "@procertus-ui/ui-lib";

import {
  REGISTRATION_PHASE_DESCRIPTION,
  REGISTRATION_PHASE_TITLE,
} from "../../anonymous-onboarding/anonymous-onboarding-constants";
import { mergeRegistrationChromeCopy } from "../../anonymous-onboarding/anonymous-onboarding-registration-chrome-copy";
import { stepIndex } from "../../anonymous-onboarding/anonymous-onboarding-flow-helpers";
import {
  baseAnonymousOnboardingFlowViewProps,
  noop,
  storyCustomerContext,
  storyOnboardingDrafts,
  storyOnboardingStepperSteps,
  storyRequestOrigin,
} from "../../anonymous-onboarding/anonymous-onboarding-story-fixtures";
import { ONBOARDING_STEPS } from "../../anonymous-onboarding/anonymous-onboarding-types";
import type { OnboardingStep } from "../../anonymous-onboarding/anonymous-onboarding-types";
import { useAnonymousOnboardingRegistrationLayoutModel } from "../../anonymous-onboarding/use-anonymous-onboarding-registration-layout-model";
import { STABLE_STEP_MIN_HEIGHT } from "../../certification-request-wizard/use-certification-request-wizard-view";

import { OnboardingCompanyStep } from "../company-step/OnboardingCompanyStep";
import { OnboardingCustomerStep } from "../customer-step/OnboardingCustomerStep";
import { OnboardingExtrasStep } from "../extras-step/OnboardingExtrasStep";
import { OnboardingInvoicingStep } from "../invoicing-step/OnboardingInvoicingStep";
import { OnboardingOriginStep } from "../origin-step/OnboardingOriginStep";
import { OnboardingShell } from "../shell/OnboardingShell";
import { OnboardingSummaryStep } from "../summary-step/OnboardingSummaryStep";

const PublicLayoutDecorator = (Story: ComponentType) => {
  useLayoutEffect(() => {
    const el = document.documentElement;
    el.dataset.publicLayout = "";
    return () => {
      delete el.dataset.publicLayout;
    };
  }, []);
  return <Story />;
};

function RegistrationChromeComposer({ initialStep }: { initialStep: Exclude<OnboardingStep, "request"> }) {
  const [step, setStep] = useState<Exclude<OnboardingStep, "request">>(initialStep);
  const [requestOrigin, setRequestOrigin] = useState<typeof storyRequestOrigin | "">(storyRequestOrigin);

  const viewProps = useMemo(
    () =>
      baseAnonymousOnboardingFlowViewProps({
        step,
        drafts: storyOnboardingDrafts,
        requestOrigin,
        context: storyCustomerContext(),
        steps: storyOnboardingStepperSteps({
          step,
          context: storyCustomerContext(),
          drafts: storyOnboardingDrafts,
          requestOrigin,
        }),
        activeStep: stepIndex(step),
        goToOnboardingStep: (next: OnboardingStep) => {
          if (next === "request") return;
          setStep(next as Exclude<OnboardingStep, "request">);
        },
        setRequestOrigin: (o: (typeof storyRequestOrigin)) => setRequestOrigin(o),
        primaryAction: { label: "Verder (demo)", onClick: noop, disabled: false },
        backAction: { label: "Terug", onClick: noop },
      }),
    [step, requestOrigin],
  );

  const model = useAnonymousOnboardingRegistrationLayoutModel(viewProps);
  const chromeStep = step;
  const registrationChrome = mergeRegistrationChromeCopy(chromeStep);

  return (
    <OnboardingShell
      pageTitle={REGISTRATION_PHASE_TITLE}
      pageDescription={REGISTRATION_PHASE_DESCRIPTION}
      onSignInClick={noop}
    >
      <StepLayout
        className="w-full"
        minHeight={STABLE_STEP_MIN_HEIGHT}
        variant="onboarding"
        stepper={
          <OnboardingStepper
            steps={viewProps.steps}
            activeStep={viewProps.activeStep}
            onStepChange={(index) => {
              const nextStep = ONBOARDING_STEPS[index];
              if (nextStep && nextStep !== "request") {
                setStep(nextStep);
              }
            }}
            interactive
          />
        }
        title={`${registrationChrome.title} (${step})`}
        description={`${registrationChrome.description} Storybook-demo: gebruik de stapregelaar hierboven of de stepper.`}
        backAction={viewProps.backAction}
        primaryAction={viewProps.primaryAction}
      >
        <StepBodies model={model} step={step} requestOrigin={requestOrigin} />
      </StepLayout>
    </OnboardingShell>
  );
}

function StepBodies({
  step,
  model,
  requestOrigin,
}: {
  step: Exclude<OnboardingStep, "request">;
  model: ReturnType<typeof useAnonymousOnboardingRegistrationLayoutModel>;
  requestOrigin: typeof storyRequestOrigin | "";
}) {
  const noopSet = (): void => {};

  switch (step) {
    case "origin":
      return (
        <OnboardingOriginStep
          originFieldBase={model.originFieldBase}
          requestOrigin={requestOrigin}
          setRequestOrigin={noopSet}
        />
      );
    case "customer":
      return <OnboardingCustomerStep model={model} />;
    case "company":
      return <OnboardingCompanyStep model={model} />;
    case "invoicing":
      return <OnboardingInvoicingStep model={model} />;
    case "extras":
      return <OnboardingExtrasStep model={model} />;
    case "summary":
      return <OnboardingSummaryStep model={model} />;
    default:
      return null as unknown as ReactNode;
  }
}

const meta = {
  title: "Onboarding/Flow compositions/Registration chrome",
  parameters: {
    layout: "fullscreen",
    docs: {
      description: {
        component:
          "Composes **`OnboardingShell` + `StepLayout` (`OnboardingStepper`) + presentational steps** mirroring registratie-phase chrome. Buttons are placeholders in Storybook; stepper navigates locally.",
      },
    },
